<script lang="ts">
  import {onMount,untrack} from 'svelte';
  import {renderAttachmentFrame,validateAttachment,ATTACHMENT_DOCUMENT_MAX_BYTES,type AttachmentDocument,type AttachmentBinding} from './attachment.ts';
  import {makeImg,bytesToBase64,base64ToBytes,pngSize,type Img} from '../../lib/image/png.ts';
  import {sha256} from '../../lib/image/hash.ts';
  import {decodePngBytes,encodePngBytes} from '../../lib/image/pngraw.ts';
  import {padImg,padOf,recompose} from '../../lib/items/items.ts';
  import {zip,type ZipEntry} from '../../lib/store/zip.ts';
  let {jobId,hashes,images,keypoints,durations,included,loop,pivot,direction}:{jobId:string;hashes:string[];images:Img[];keypoints:{label:string;x:number;y:number}[][];durations:number[];included:boolean[];loop:boolean;pivot:{x:number;y:number};direction:string}=$props();
  let doc=$state<AttachmentDocument>(),index=$state(0),error=$state(''),status=$state(''),playing=$state(false),mode=$state('grip'),radius=$state(2),canvas=$state<HTMLCanvasElement>(),assetCanvas=$state<HTMLCanvasElement>(),dragging=false;
  let preview=$state<Img>(),hidden=$state(0),clipped=$state(0),asset=$state<Img>(),previewError=$state('');
  let guides=$state(true),sourcePoint=$state<'grip'|'axis'>('grip');
  // The parent keys this editor by the completed job, so its binding is immutable.
  const binding:AttachmentBinding=untrack(()=>({jobId,hashes,cell:{w:images[0].w,h:images[0].h},pivot,direction,padding:Math.max(padOf('main_hand','skel',images[0]),Math.min(64,Math.ceil(images[0].w/2)))})),padding=binding.padding,storage='pixeldoll.motionAttachment.'+binding.jobId;
  let painting:Promise<void>=Promise.resolve();
  const download=(name:string,data:BlobPart,type='application/json')=>{const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  async function assetImported(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>2_000_000)throw new Error('Attachment PNG exceeds 2 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),image=await decodePngBytes(bytes);if(image.w>512||image.h>512)throw new Error('Attachment PNG exceeds 512 px.');const blank=bytesToBase64(await encodePngBytes(makeImg(images[0].w+2*padding,images[0].h+2*padding)));doc={version:1,kind:'pixeldoll-authored-attachment',body:binding,asset:{png:bytesToBase64(bytes),grip:{x:image.w/2,y:image.h/2},axis:{x:image.w/2,y:0}},frames:images.map((_,i)=>{const wrist=keypoints[i]?.find(k=>k.label==='RIGHT ARM');if(!wrist)throw new Error('Frozen frame has no right wrist reference.');return{grip:{x:wrist.x*images[0].w+padding,y:wrist.y*images[0].h+padding},angle:-90,occluder:blank}}),notes:''};index=0;playing=false;error='';status='Calibrate source grip/axis, then author each target grip, angle and occlusion.';}catch(e){error=(e as Error).message;}}
  async function imported(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>ATTACHMENT_DOCUMENT_MAX_BYTES)throw new Error('Attachment document exceeds 5 MB.');doc=validateAttachment(JSON.parse(await file.text()),binding);index=0;playing=false;error='';status='Loaded authored attachment for these exact frozen frames.';}catch(e){error=(e as Error).message;}}
  async function frameImported(event:Event){try{const file=(event.target as HTMLInputElement).files?.[0];if(!file||!doc)return;const current=doc,frame=doc.frames[index],selected=index;playing=false;if(file.size>2_000_000)throw new Error('Authored frame PNG exceeds 2 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),size=pngSize(bytes),w=images[0].w+2*padding,h=images[0].h+2*padding;if(size?.w!==w||size.h!==h)throw new Error(`Authored frame PNG must be ${w} by ${h} pixels. Export the native frame first; do not resize it.`);const image=await decodePngBytes(bytes);if(image.data.some((v,i)=>i%4===3&&v!==0&&v!==255))throw new Error('Authored frame PNG must use opaque or transparent pixels, without partial alpha.');if(doc!==current)throw new Error('The attachment changed while loading. Import the frame again.');const encoded=bytesToBase64(bytes);validateAttachment({...doc,frames:doc.frames.map(f=>f===frame?{...f,authoredPng:encoded}:f)},binding);frame.authoredPng=encoded;status=`Loaded native item art for frame ${selected+1}. Body pixels are unchanged; review grip and body occlusion.`;error='';}catch(e){error=(e as Error).message;}finally{(event.target as HTMLInputElement).value='';}}
  async function save(){try{await painting;if(!doc)return;validateAttachment(JSON.parse(JSON.stringify(doc)),binding);localStorage.setItem(storage,JSON.stringify(doc));status='Attachment draft saved locally.';error='';}catch(e){error=(e as Error).message;}}
  async function saveDocument(){try{await painting;if(!doc)return;const value=validateAttachment(JSON.parse(JSON.stringify(doc)),binding);download(`attachment-${jobId}.json`,JSON.stringify(value));}catch(e){error=(e as Error).message;}}
  async function pack(){try{await painting;if(!doc)return;const plain=validateAttachment(JSON.parse(JSON.stringify(doc)),binding),source=await decodePngBytes(base64ToBytes(plain.asset.png)),entries:ZipEntry[]=[],frames=[];
    for(let i=0;i<images.length;i++){const body=padImg(images[i],padding),f=plain.frames[i],out=await renderAttachmentFrame(source,plain.asset,f,body);entries.push({name:`body/${i}.png`,data:await encodePngBytes(body)},{name:`layers/${i}.png`,data:await encodePngBytes(out.image)},{name:`preview/${i}.png`,data:await encodePngBytes(recompose({base:body,layer:out.image}))});frames.push({index:i,bodySha:hashes[i],ms:durations[Math.min(i,durations.length-1)],included:included[i],source:out.source,...(f.authoredPng?{authoredFrameSha256:await sha256(base64ToBytes(f.authoredPng))}:{}),hiddenPixels:out.hidden,clippedSourcePixels:out.clippedSourcePixels});}
    entries.push({name:'authoring.json',data:new TextEncoder().encode(JSON.stringify(plain,null,2))},{name:'manifest.json',data:new TextEncoder().encode(JSON.stringify({kind:'pixeldoll-authored-attachment-research',qualified:false,loop,cell:{w:images[0].w+2*padding,h:images[0].h+2*padding},pivot:{x:pivot.x+padding,y:pivot.y+padding},direction,frames,note:'Frozen body pixels are unchanged. Calibrated source placement or native frame art and body-only occluders; visual qualification remains separate.'},null,2))});download(`attachment-${jobId}.zip`,(await zip(entries)) as Uint8Array<ArrayBuffer>,'application/zip');status='Exported native body/layer frames, authored metadata and timing.';error='';}catch(e){error=(e as Error).message;}}
  function draw(target:HTMLCanvasElement,image:Img){target.width=image.w;target.height=image.h;target.getContext('2d')!.putImageData(new ImageData(new Uint8ClampedArray(image.data),image.w,image.h),0,0);}
  function guide(target:HTMLCanvasElement,point:{x:number;y:number},axis=false){const ctx=target.getContext('2d')!;ctx.save();ctx.beginPath();if(axis)ctx.rect(point.x-2,point.y-2,4,4);else ctx.arc(point.x,point.y,2,0,2*Math.PI);ctx.strokeStyle='#000';ctx.lineWidth=3;ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=1;ctx.stroke();ctx.restore();}
  function canvasPoint(event:PointerEvent,target:HTMLCanvasElement){const rect=target.getBoundingClientRect();return{x:Math.max(0,Math.min(target.width-0.5,(event.clientX-rect.left)*target.width/rect.width)),y:Math.max(0,Math.min(target.height-0.5,(event.clientY-rect.top)*target.height/rect.height))};}
  function sourceMarked(event:PointerEvent){if(!doc||!assetCanvas)return;playing=false;const p=canvasPoint(event,assetCanvas);doc.asset[sourcePoint]={x:Math.floor(p.x)+0.5,y:Math.floor(p.y)+0.5};status=sourcePoint==='grip'?'Source grip moved. Place this point inside the shaft where the palm closes.':'Source direction moved. This point defines the blade direction.';error='';}
  $effect(()=>{if(!doc||!images[index])return;let disposed=false;const source=$state.snapshot(doc.asset),frame=$state.snapshot(doc.frames[index]),body=padImg(images[index],padding);
    // A previous good image must never stand in for the newly selected frame or invalid placement.
    preview=undefined;asset=undefined;hidden=0;clipped=0;previewError='';
    void(async()=>{const a=await decodePngBytes(base64ToBytes(source.png)),out=await renderAttachmentFrame(a,source,frame,body);if(disposed)return;asset=a;hidden=out.hidden;clipped=out.clippedSourcePixels;preview=recompose({base:body,layer:out.image});})().catch(e=>{if(!disposed){previewError=(e as Error).message;playing=false;}});return()=>{disposed=true};});
  $effect(()=>{if(canvas){if(preview){draw(canvas,preview);if(guides&&doc&&!doc.frames[index].authoredPng)guide(canvas,doc.frames[index].grip);}else canvas.getContext('2d')!.clearRect(0,0,canvas.width,canvas.height);}if(assetCanvas){if(asset){draw(assetCanvas,asset);if(guides&&doc){guide(assetCanvas,doc.asset.grip);guide(assetCanvas,doc.asset.axis,true);}}else assetCanvas.getContext('2d')!.clearRect(0,0,assetCanvas.width,assetCanvas.height);}});
  $effect(()=>{if(doc?.frames[index]?.authoredPng&&mode==='grip')mode='paint';});
  $effect(()=>{if(!playing||!doc)return;const last=included.lastIndexOf(true);if(last<0){playing=false;return;}const timer=setTimeout(()=>{if(index===last&&!loop){playing=false;return;}do{index=(index+1)%images.length}while(!included[index]);},durations[Math.min(index,durations.length-1)]??120);return()=>clearTimeout(timer)});
  function paint(event:PointerEvent){if(!doc||!canvas||!dragging)return;playing=false;const{x,y}=canvasPoint(event,canvas),frame=doc.frames[index],action=mode,brush=radius;if(action==='grip'){if(frame.authoredPng){error='Native frame art fixes placement. Paint occlusion or restore source placement.';return;}frame.grip={x,y};return;}
    // Queue strokes against the captured frame, including when the user switches frames during PNG encoding.
    painting=painting.then(async()=>{const next=await decodePngBytes(base64ToBytes(frame.occluder));for(let py=Math.max(0,Math.floor(y-brush));py<Math.min(next.h,Math.ceil(y+brush));py++)for(let px=Math.max(0,Math.floor(x-brush));px<Math.min(next.w,Math.ceil(x+brush));px++)if(Math.hypot(px+0.5-x,py+0.5-y)<=brush)next.data.set(action==='paint'?[255,255,255,255]:[0,0,0,0],(py*next.w+px)*4);frame.occluder=bytesToBase64(await encodePngBytes(next));}).catch(e=>{error=(e as Error).message});}
  onMount(()=>{try{const text=localStorage.getItem(storage);if(text)doc=validateAttachment(JSON.parse(text),binding)}catch(e){error=(e as Error).message}});
</script>
<section class="attachment bu-stack" aria-label="Authored held item">
  <h4>Authored held item</h4><p>Use a transparent directional weapon layer. Calibrate its source grip and blade-axis point, then author target grip, angle and body occluders per frozen frame. Import native item art for individual frames when rotation cannot draw the required perspective. These controls cost no generations.</p>
  <div class="bu-actions"><label>Attachment PNG<input type="file" accept="image/png" onchange={assetImported}></label><label>Import attachment document<input type="file" accept="application/json" onchange={imported}></label></div>
  {#if error||previewError}<p role="alert" class="bu-error">{[error,previewError].filter(Boolean).join(' ')}</p>{/if}<p role="status">{status}</p>
  {#if doc}
    <div class="bu-actions"><label>Source point<select class="bu-select" bind:value={sourcePoint}><option value="grip">Grip inside handle</option><option value="axis">Blade direction</option></select></label><label><input type="checkbox" bind:checked={guides}>Show grip guides</label></div>
    <p>Click the source art to place its grip inside the shaft, not at its end. Place the target grip in the palm so the shaft passes behind the fingers. Circle: grip; square: direction. Hide guides to judge the actual art. Guides are not exported.</p>
    <p>Native item canvas: {images[0].w+2*padding} by {images[0].h+2*padding} pixels. Export the attachment to obtain aligned frames for drawing. Import only the transparent item layer.</p>
    <div class="bu-actions"><label>Authored frame PNG<input type="file" accept="image/png" onchange={frameImported}></label><button class="bu-btn" disabled={!doc.frames[index].authoredPng} onclick={()=>{delete doc!.frames[index].authoredPng;status='Restored calibrated source placement for this frame.';error='';}}>Use source placement for this frame</button></div>
    <p>Frame {index+1}: {doc.frames[index].authoredPng?'native authored art; grip and angle placement are bypassed':'calibrated source placement'}. Body occlusion applies to both.</p>
    <div class="views"><figure><figcaption>Directional source art</figcaption><canvas bind:this={assetCanvas} aria-label="Attachment source artwork" onpointerdown={sourceMarked}></canvas></figure><figure><figcaption>Frozen body and authored layer, frame {index+1}/{images.length}</figcaption><canvas bind:this={canvas} aria-label="Attachment grip and occlusion editor" onpointerdown={e=>{dragging=true;canvas!.setPointerCapture(e.pointerId);void paint(e)}} onpointermove={e=>void paint(e)} onpointerup={()=>dragging=false} onpointercancel={()=>dragging=false}></canvas></figure></div>
    <div class="fields">{#each ['grip','axis'] as point}{#each ['x','y'] as axis}<label>Source {point} {axis}<input class="bu-input" type="number" step="0.5" bind:value={doc.asset[point as 'grip'|'axis'][axis as 'x'|'y']}></label>{/each}{/each}</div>
    <div class="bu-actions"><button class="bu-btn" onclick={()=>{if(!included.some(Boolean))return;if(!playing&&(!included[index]||(!loop&&index===included.lastIndexOf(true))))index=included.indexOf(true);playing=!playing}}>{playing?'Pause authored attachment':'Play authored attachment'}</button>{#each images as _,i}<button class="bu-btn" aria-label={`Author attachment frame ${i+1}`} aria-pressed={index===i} onclick={()=>{index=i;playing=false}}>{i+1}{included[i]?'':' excluded'}</button>{/each}</div>
    <div class="fields"><label>Target grip X, px<input class="bu-input" type="number" step="0.5" disabled={!!doc.frames[index].authoredPng} bind:value={doc.frames[index].grip.x}></label><label>Target grip Y, px<input class="bu-input" type="number" step="0.5" disabled={!!doc.frames[index].authoredPng} bind:value={doc.frames[index].grip.y}></label><label>Blade angle, degrees<input class="bu-input" type="number" step="5" disabled={!!doc.frames[index].authoredPng} bind:value={doc.frames[index].angle}></label><label>Canvas action<select class="bu-select" bind:value={mode}><option value="grip" disabled={!!doc.frames[index].authoredPng}>Place grip</option><option value="paint">Paint body occlusion</option><option value="erase">Erase occlusion</option></select></label><label>Occlusion brush, px<input class="bu-input" type="number" min="1" max="12" bind:value={radius}></label></div>
    <p>{#if preview}{hidden} item pixels hidden by the body mask. {doc.frames[index].authoredPng?'Native art defines its own bounds; inspect it for missing or cropped details.':`${clipped} source pixels clip outside the canvas.`} Painting affects only the item layer where frozen body pixels exist.{:else if previewError}Frame preview unavailable. Correct the rendering error before judging this frame.{:else}Rendering selected frame…{/if}</p>
    <label>Attachment review notes<textarea class="bu-input" bind:value={doc.notes}></textarea></label><div class="bu-actions"><button class="bu-btn" onclick={save}>Save attachment draft</button><button class="bu-btn" onclick={saveDocument}>Save attachment document</button><button class="bu-btn" onclick={pack}>Export authored attachment</button></div>
  {/if}
</section>
<style>.attachment{padding:16px}.views{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.views figure{margin:0}.views canvas{width:100%;height:auto;image-rendering:pixelated;touch-action:none}.fields{display:flex;gap:12px;flex-wrap:wrap}.fields label{width:150px}.attachment textarea{min-height:80px}@media(max-width:560px){.views{grid-template-columns:1fr}}</style>
